function divideNoSlash(dividend: number, divisor: number): number {
  const MAX = 2147483647, MIN = -2147483648;
  if (dividend === MIN && divisor === -1) return MAX;
  const negative = (dividend < 0) !== (divisor < 0);
  let a = Math.abs(dividend), b = Math.abs(divisor), q = 0;
  while (a >= b) {
    let chunk = b, count = 1;
    while (chunk + chunk <= a) { chunk += chunk; count += count; }
    a -= chunk;
    q += count;
  }
  return negative ? -q : q;
}

