function divideNoSlash(dividend: number, divisor: number): number {
  const MAX = 2147483647, MIN = -2147483648;
  if (dividend === MIN && divisor === -1) return MAX;
  const negative = (dividend < 0) !== (divisor < 0);
  const a = Math.abs(dividend), b = Math.abs(divisor); // a ≤ 2³¹ fits an unsigned 32-bit shift
  let rem = 0, q = 0;
  for (let i = 31; i >= 0; i--) {
    rem = rem + rem + ((a >>> i) & 1);
    q = q + q;
    if (rem >= b) { rem -= b; q += 1; }
  }
  return negative ? -q : q;
}

